package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

// SalesRec mirrors FD SALES-FILE record
type SalesRec struct {
	SrId    string
	SrSales decimal.Decimal
}

type TierEntry struct {
	TierLimit decimal.Decimal
	TierRate  decimal.Decimal
}

// Working storage
var WsEofFlag string = "N"
var WsIdx int64 = 0
var WsTier int64 = 0
var WsComm decimal.Decimal = decimal.NewFromInt(0)
var WsTotal decimal.Decimal = decimal.NewFromInt(0)
var WsCount int64 = 0
var WsSalesEd string
var WsRateEd string
var WsCommEd string
var WsTotalEd string

var salesRec SalesRec
var tierTable [5]TierEntry // 1-based, 0 unused

var salesFileLines []string
var salesFilePos int

func parseDecimalFromDigits(s string, scale int32) decimal.Decimal {
	s = strings.TrimSpace(s)
	if s == "" {
		return decimal.NewFromInt(0)
	}
	// s should be digits only; if it contains spaces keep only digits?
	// Keep digits, ignore other?
	// Extract digits and possible sign
	neg := false
	if strings.HasPrefix(s, "-") {
		neg = true
		s = s[1:]
	}
	digits := ""
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			digits += string(ch)
		}
	}
	if digits == "" {
		return decimal.NewFromInt(0)
	}
	// parse as integer
	d, err := decimal.NewFromString(digits)
	if err != nil {
		return decimal.NewFromInt(0)
	}
	// shift by -scale : divide by 10^scale
	d = d.Shift(-scale)
	if neg {
		d = d.Neg()
	}
	return d
}

func storeDecimal(v decimal.Decimal, intDigits int, scale int32, rounded bool) decimal.Decimal {
	if rounded {
		v = v.Round(scale)
	} else {
		v = v.Truncate(scale)
	}
	// overflow: keep low-order digits
	// Need to keep (intDigits + scale) decimal digits total
	// low-order digits means modulo 10^(intDigits+scale) on the scaled integer
	// v = scaledInt * 10^{-scale}
	// scaledInt = v *10^{scale} as integer
	scaledInt := v.Shift(scale).Truncate(0)
	// compute modulus = 10^(intDigits+scale)  (for positive and negative? cobol high-order truncation keeps low order digits ignoring sign)
	// Use decimal pow
	modStr := "1" + strings.Repeat("0", intDigits+int(scale))
	mod, _ := decimal.NewFromString(modStr)
	// For negative numbers, COBOL keeps sign? We'll handle magnitude
	neg := scaledInt.IsNegative()
	absScaled := scaledInt.Abs()
	if absScaled.Cmp(mod) >= 0 {
		absScaled = absScaled.Mod(mod)
		scaledInt = absScaled
		if neg {
			scaledInt = scaledInt.Neg()
		}
	}
	return scaledInt.Shift(-scale)
}

func formatEdited(value decimal.Decimal, picture string) string {
	// picture contains Z , 9 . only
	dotIdx := strings.Index(picture, ".")
	var intPic, decPic string
	if dotIdx >= 0 {
		intPic = picture[:dotIdx]
		decPic = picture[dotIdx+1:]
	} else {
		intPic = picture
		decPic = ""
	}
	decDigits := len(decPic)
	// count digit placeholders in intPic
	// digit placeholders are Z and 9
	// prepare integer string
	// get absolute value and sign (prices not negative here)
	neg := value.IsNegative()
	absVal := value.Abs()

	// quantize to decDigits by truncating (MOVE does not round, just format)
	// However edited move should just display existing value which already has correct scale.
	// Ensure dec part exists: format with decDigits
	var intStr, decStr string
	if decDigits > 0 {
		// Use StringFixed to get exactly decDigits decimal places (rounded? we want truncated)
		// But value already at scale decDigits, trunc = same. Use Truncate then StringFixed.
		absVal = absVal.Truncate(int32(decDigits))
		s := absVal.StringFixed(int32(decDigits))
		parts := strings.SplitN(s, ".", 2)
		intStr = parts[0]
		if len(parts) > 1 {
			decStr = parts[1]
		} else {
			decStr = strings.Repeat("0", decDigits)
		}
		// handle negative zero?
		if intStr == "" {
			intStr = "0"
		}
		if intStr[0] == '-' {
			intStr = intStr[1:]
		}
	} else {
		absVal = absVal.Truncate(0)
		s := absVal.StringFixed(0)
		// StringFixed(0) may include "."
		if idx := strings.Index(s, "."); idx >= 0 {
			intStr = s[:idx]
		} else {
			intStr = s
		}
		if intStr == "" {
			intStr = "0"
		}
		if strings.HasPrefix(intStr, "-") {
			intStr = intStr[1:]
		}
		decStr = ""
	}
	// handle overflow of integer digits: keep low-order digits
	intPlaceholders := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intPlaceholders++
		}
	}
	if len(intStr) > intPlaceholders {
		intStr = intStr[len(intStr)-intPlaceholders:]
	}
	// Build output for int part
	outInt := make([]byte, len(intPic))
	// fill from right to left
	p := len(intStr) - 1
	for i := len(intPic) - 1; i >= 0; i-- {
		ch := intPic[i]
		if ch == 'Z' || ch == '9' {
			if p >= 0 {
				outInt[i] = intStr[p]
				p--
			} else {
				outInt[i] = '0'
			}
		} else {
			outInt[i] = byte(ch) // comma
		}
	}
	// Z suppression
	suppressed := true
	for i := 0; i < len(intPic); i++ {
		pch := intPic[i]
		if pch == ',' {
			if suppressed {
				outInt[i] = ' '
			}
			// comma does not change suppressed state
		} else if pch == 'Z' {
			if suppressed && outInt[i] == '0' {
				outInt[i] = ' '
			} else {
				suppressed = false
			}
		} else if pch == '9' {
			suppressed = false
		}
	}
	// Build final
	var sb strings.Builder
	sb.Write(outInt)
	if decDigits > 0 {
		sb.WriteByte('.')
		// decStr already correct length; pad if needed
		if len(decStr) < decDigits {
			decStr = decStr + strings.Repeat("0", decDigits-len(decStr))
		} else if len(decStr) > decDigits {
			decStr = decStr[:decDigits]
		}
		sb.WriteString(decStr)
	}
	result := sb.String()
	// handle negative sign: COBOL edited pictures in this program have no sign; ignore
	if neg && result != "" {
		// place '-' at leftmost non-space? Not needed for this program
		// just prefix
		// Find first non-space
		for i, c := range result {
			if c != ' ' && c != ',' && c != '.' {
				b := []byte(result)
				// if there's a space before, put '-'
				if i > 0 && b[i-1] == ' ' {
					b[i-1] = '-'
					result = string(b)
				} else {
					// otherwise prefix (will exceed width, but unlikely)
					result = "-" + result[1:]
				}
				break
			}
		}
	}
	// Ensure length equals picture length
	if len(result) != len(picture) {
		// pad or truncate to picture length
		if len(result) < len(picture) {
			result = strings.Repeat(" ", len(picture)-len(result)) + result
		} else if len(result) > len(picture) {
			result = result[len(result)-len(picture):]
		}
	}
	return result
}

func formatUneditedInt(v int64, digits int) string {
	// keep low-order digits
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	if digits < 19 {
		// handle overflow: keep low order
		// for negative not needed
		if v >= mod || v <= -mod {
			v = v % mod
			if v < 0 {
				v = -v
			}
		}
	}
	// zero padded
	fmtStr := fmt.Sprintf("%%0%dd", digits)
	return fmt.Sprintf(fmtStr, v)
}

// COBOL paragraphs as Go functions

func mainPara() {
	initPara()
	openInput()
	readPara()
	for WsEofFlag != "Y" {
		processPara()
	}
	closeInput()
	summaryPara()
}

func initPara() {
	tierTable[1].TierLimit = decimal.NewFromFloat(1000.00)
	tierTable[1].TierRate = decimal.NewFromFloat(2.50)
	tierTable[2].TierLimit = decimal.NewFromFloat(5000.00)
	tierTable[2].TierRate = decimal.NewFromFloat(4.00)
	tierTable[3].TierLimit = decimal.NewFromFloat(20000.00)
	tierTable[3].TierRate = decimal.NewFromFloat(5.50)
	tierTable[4].TierLimit = decimal.NewFromFloat(999999.99)
	tierTable[4].TierRate = decimal.NewFromFloat(7.25)
	// Ensure correct scale truncation
	tierTable[1].TierLimit = tierTable[1].TierLimit.Truncate(2)
	tierTable[2].TierLimit = tierTable[2].TierLimit.Truncate(2)
	tierTable[3].TierLimit = tierTable[3].TierLimit.Truncate(2)
	tierTable[4].TierLimit = tierTable[4].TierLimit.Truncate(2)
	tierTable[1].TierRate = tierTable[1].TierRate.Truncate(2)
	tierTable[2].TierRate = tierTable[2].TierRate.Truncate(2)
	tierTable[3].TierRate = tierTable[3].TierRate.Truncate(2)
	tierTable[4].TierRate = tierTable[4].TierRate.Truncate(2)
}

func openInput() {
	f, err := os.Open("input.dat")
	if err != nil {
		// no file => EOF immediately, create empty list
		salesFileLines = []string{}
		salesFilePos = 0
		return
	}
	defer f.Close()
	scanner := bufio.NewScanner(f)
	// allow long lines
	const maxCap = 1024 * 1024
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, maxCap)
	var lines []string
	for scanner.Scan() {
		line := scanner.Text()
		// scanner strips \r and \n, but we need to handle \r leftover?
		// Keep line as is; if file had \r\n, scanner will trim \r? Actually it trims \n only, leaves \r? In Go, ScanLines trims \r\n.
		// It removes trailing \r if present.
		lines = append(lines, line)
	}
	salesFileLines = lines
	salesFilePos = 0
}

func closeInput() {
	// nothing
}

func readPara() {
	if salesFilePos >= len(salesFileLines) {
		WsEofFlag = "Y"
		return
	}
	raw := salesFileLines[salesFilePos]
	salesFilePos++

	// LINE SEQUENTIAL: pad with spaces on right if shorter than 12
	if len(raw) < 12 {
		raw = raw + strings.Repeat(" ", 12-len(raw))
	} else if len(raw) > 12 {
		raw = raw[:12]
	}
	// parse fields
	srId := raw[0:4]
	srSalesRaw := raw[4:12]
	salesRec.SrId = srId
	salesRec.SrSales = parseDecimalFromDigits(srSalesRaw, 2)
	// truncate to PIC 9(6)V99 (just in case)
	salesRec.SrSales = storeDecimal(salesRec.SrSales, 6, 2, false)
	WsEofFlag = "N"
}

func processPara() {
	WsTier = 0
	for WsIdx = 1; WsIdx <= 4 && !(WsTier > 0); WsIdx++ {
		if salesRec.SrSales.Cmp(tierTable[WsIdx].TierLimit) <= 0 {
			WsTier = WsIdx
		}
	}
	// COMPUTE WS-COMM ROUNDED = SR-SALES * TIER-RATE (WS-TIER) / 100
	rate := tierTable[WsTier].TierRate
	// multiply before dividing
	computed := salesRec.SrSales.Mul(rate).Shift(-2)
	// ROUNDED to scale 2
	WsComm = storeDecimal(computed, 6, 2, true)

	WsTotal = WsTotal.Add(WsComm)
	// ensure WsTotal stays within 9(9)V99 truncating high-order? apply store
	WsTotal = storeDecimal(WsTotal, 9, 2, false)

	WsCount = WsCount + 1
	if WsCount > 999 {
		WsCount = WsCount % 1000
	}

	WsSalesEd = formatEdited(salesRec.SrSales, "ZZZ,ZZ9.99")
	WsRateEd = formatEdited(rate, "9.99")
	WsCommEd = formatEdited(WsComm, "ZZZ,ZZ9.99")

	// DISPLAY
	tierStr := formatUneditedInt(WsTier, 1)
	// SR-ID is X(4) exactly 4 chars
	fmt.Printf("%s T%s %s %s%% %s\n", salesRec.SrId, tierStr, WsSalesEd, WsRateEd, WsCommEd)

	readPara()
}

func summaryPara() {
	WsTotalEd = formatEdited(WsTotal, "ZZZ,ZZZ,ZZ9.99")
	countStr := formatUneditedInt(WsCount, 3)
	fmt.Printf("REPS: %s TOTAL: %s\n", countStr, WsTotalEd)
}

func main() {
	mainPara()
}
